NAME = 'SrKDIjekav: Serbian Bible Daničić-Karadžić Ijekavski'
BOOK = 'Micah'

CHAPTERS = {
    1: {
        1: 'Ријеч Господња која дође Михеју Моресећанину за времена Јоатама, Ахаза и Језекије, царева Јудинијех, што видје за Самарију и за Јерусалим.',
        2: 'Чујте, сви народи, слушај, земљо и што је на њој, и Господ Бог да вам је свједок, Господ из свете цркве своје.',
        3: 'Јер, гле, Господ излази из мјеста својега, и сићи ће, и ходиће по висинама земаљским.',
        4: 'И горе ће се растопити пред њим, и долине ће се расјести, као восак од огња и као вода што тече низ стрмен.',
        5: 'Све је то за злочинство Јаковљево и за гријехе дома Израиљева. Које је злочинство Јаковљево? није ли Самарија? које су висине Јудине? није ли Јерусалим?',
        6: 'Зато ћу учинити од Самарије гомилу у пољу да се саде виногради, и побацаћу камење њезино у долину и открићу јој темеље.',
        7: 'И сви резани ликови њезини разбиће се, и сви ће се дарови њезини сажећи огњем, и све ћу идоле њезине потрти, јер од плате курварске накупи, и опет ће бити плата курварска.',
        8: 'Зато ћу плакати и ридати; ходићу свучен и го; плакаћу као змајеви и тужићу као сове.',
        9: 'Јер јој се ране не могу исцијелити, дођоше до Јуде, допријеше до врата мојега народа, до Јерусалима.',
        10: 'Не јављајте у Гату, не плачите; у Вит-Афри ваљај се по праху.',
        11: 'Изиди, становнице Сафирска, с голом срамотом; становница Сананска неће изаћи; жалост Вет-езилска неће вам дати станка.',
        12: 'Јер становница Маротска тужи за својим добром. Јер сиђе зло од Господа до врата Јерусалимских.',
        13: 'Упрегни брзе коње у кола, становнице Лахиска, која си почетак гријеху кћери Сионској, јер се у теби нађоше злочинства Израиљева.',
        14: 'Зато пошљи даре Моресету Гатском; домови Ахсивски превариће цареве Израиљеве.',
        15: 'Још ћу ти довести нашљедника, становнице Мариска; доћи ће до Одолама, славе Израиљеве.',
        16: 'Начини се ћелава и остризи се за милом дјецом својом; рашири ћелу своју као орао, јер се воде од тебе у ропство.',
    },
    2: {
        1: 'Тешко онима који смишљају безакоње и о злу се труде на постељама својим, и кад сване извршују, јер им је сила у руци.',
        2: 'Желе њиве, и отимају их; желе куће, и узимају; чине силу човјеку и кући његовој, човјеку и нашљедству његову.',
        3: 'Зато овако вели Господ: ево, ја мислим зло томе роду, из којега нећете извући вратова својих, нити ћете ходити поносито, јер ће бити зло вријеме.',
        4: 'У оно вријеме говориће се прича о вама, и нарицаће се жалосно говорећи: пропадосмо; промијени дио народа мојега; како ми узе! узевши њиве наше раздијели.',
        5: 'Зато нећеш имати никога ко би ти повукао уже за ждријеб у збору Господњем.',
        6: 'Немојте пророковати, нека они пророкују; ако им не пророкују, неће отступити срамота.',
        7: 'О ти, који се зовеш дом Јаковљев, је ли се умалио дух Господњи? јесу ли то дјела његова? еда ли моје ријечи нијесу добре ономе који ходи право?',
        8: 'А народ се мој прије подиже као непријатељ; преко хаљине скидате плашт с онијех који пролазе не бојећи се, који се враћају из боја.',
        9: 'Жене народа мојега изгоните из милијех кућа њиховијех, од дјеце њихове отимате славу моју навијек.',
        10: 'Устаните и идите, јер ово није почивалиште; што се оскврни, погубиће вас погибљу великом.',
        11: 'Ако ко ходи за вјетром и казује лажи говорећи: пророковаћу ти за вино и за силовито пиће; тај ће бити пророк овоме народу.',
        12: 'Доиста ћу те сабрати свега, Јакове, доиста ћу скупити остатак Израиљев; поставићу их заједно као овце Восорске, као стадо усред тора њихова, биће врева од људства.',
        13: 'Пред њима ће ићи који разбија; они ће разбити и проћи кроз врата, и изаћи ће; и цар ће њихов ићи пред њима, и Господ ће бити пред њима.',
    },
    3: {
        1: 'Зато рекох: чујте, поглавице Јаковљеве и кнезови дома Израиљева, не треба ли вам знати шта је право?',
        2: 'Који мрзите на добро а љубите зло, садирете кожу с њих и месо с кости њиховијех;',
        3: 'И једете месо народа мојега и садирете кожу с њих и кости им пребијате, и сасијецате као у лонац и као месо у котао.',
        4: 'Тада ће викати ка Господу, али их неће услишити, него ће сакрити лице своје од њих у оно вријеме, како они зло радише.',
        5: 'Овако вели Господ за пророке који заводе мој народ, који гризу зубима својим и вичу: мир; и ако им ко не да ништа у уста, дижу рат на њ.',
        6: 'Зато ће вам утвара бити ноћ и прорицање ваше тама; и сунце ће заћи тијем пророцима и дан ће им се смрачити.',
        7: 'Тада ће се постидјети видиоци, и врачари ће се посрамити, и сви ће застријети усне своје, јер неће бити одговора Божијега.',
        8: 'Али ја сам пун силе од духа Господњега, и суда и храбрости да кажем Јакову злочинство његово и Израиљу гријех његов.',
        9: 'Чујте ово, поглавице дома Јаковљева и кнезови дома Израиљева, који се гадите на правду, и све што је право изврћете;',
        10: 'Који градите Сион крвљу и Јерусалим безакоњем.',
        11: 'Поглавари његови суде по миту, и свештеници његови уче за плату, и пророци његови гатају за новце, а на Господа се ослањају говорећи: није ли Господ усред нас? неће доћи зло на нас.',
        12: 'Зато ће се с вас Сион преорати као њива, и Јерусалим ће постати гомила, и гора од дома висока шума.',
    },
    4: {
        1: 'Али ће у пошљедња времена бити утврђена гора дома Господњега наврх гора и узвишена изнад хумова, и народи ће се стјецати к њој.',
        2: 'И ићи ће многи народи говорећи: ходите, да идемо на гору Господњу и у дом Бога Јаковљева, и учиће нас својим путовима, и ходићемо његовијем стазама; јер ће из Сиона изаћи закон и ријеч Господња из Јерусалима.',
        3: 'И судиће међу многим народима, и покараће јаке народе надалеко, и они ће расковати мачеве своје на раонике, и копља своја на српове; неће дизати мача народ на народ, нити ће се више учити рату.',
        4: 'Него ће сједјети сваки под својом виновом лозом и под смоквом, и неће бити никога да их плаши; јер уста Господа над војскама рекоше.',
        5: 'Јер ће сви народи ходити сваки у име бога својега; а ми ћемо ходити у име Господа Бога својега увијек и довијека.',
        6: 'У то вријеме, говори Господ, сабраћу хроме, и скупићу одагнане и којима зло учиних.',
        7: 'И учинићу од хромијех остатак и од одагнаних силан народ; и Господ ће царовати над њима на гори Сиону отсада и довијека.',
        8: 'И ти, куло стаду, стијено кћери Сионској, теби ће доћи, доћи ће прва власт, царство кћери Јерусалимске.',
        9: 'Зашто вичеш тако јако? нема ли цара у теби? еда ли изгибоше твоји савјетници, те те обузеше болови као породиљу?',
        10: 'Мучи се и вичи, кћери Сионска, као породиља, јер ћеш изаћи из града и становаћеш у пољу, и отићи ћеш у Вавилон; ондје ћеш се ослободити, ондје ће те искупити Господ из руку непријатеља твојих.',
        11: 'А сада се сабраше на те многи народи говорећи: да се оскврни, и да се очи наше нагледају Сиона.',
        12: 'Али не знају мисли Господњих, нити разумију намјере његове, јер их је скупио као снопље на гумно.',
        13: 'Устани и врси, кћери Сионска, јер ћу ти начинити рог гвозден, и копита ћу ти начинити мједена, те ћеш сатрти многе народе, и посветићу Господу благо њихово и имање њихово Господу све земље.',
    },
    5: {
        1: 'Сабери се сада у чете, четнице, опсједи нас, нека бију прутом по образу судију Израиљева.',
        2: 'А ти, Витлејеме Ефрато, ако и јеси најмањи међу тисућама Јудинијем, из тебе ће ми изаћи који ће бити господар у Израиљу, којему су изласци од почетка, од вјечнијех времена.',
        3: 'Зато ће их оставити докле не роди она која ће родити; тада ће се остатак браће његове вратити са синовима Израиљевијем.',
        4: 'И стајаће и пашће их силом Господњом, величанством имена Господа Бога својега; и они ће наставати, јер ће он тада бити велик до крајева земаљских.',
        5: 'И он ће бити мир; кад дође Асирац у нашу земљу, и кад ступи у дворе наше, тада ћемо подигнути на њ седам пастира и осам кнезова из народа.',
        6: 'И они ће опасти земљу Асирску мачем и земљу Невродову на вратима његовијем; и он ће нас избавити од Асирца кад дође у нашу земљу и кад ступи на међу нашу.',
        7: 'И остатак ће Јаковљев бити усред многих народа као роса од Господа и као ситан дажд по трави, која не чека човјека нити се узда у синове човјечије.',
        8: 'И остатак ће Јаковљев бити међу народима, усред многих народа, као лав међу звијерима шумским, као лавић међу стадима оваца, који кад иде тлачи и растрже и нема никога да избави.',
        9: 'Рука ће ти се узвисити над противницима твојим, и сви ће се непријатељи твоји истријебити.',
        10: 'И у оно ћу вријеме, говори Господ, истријебити коње исред тебе и потрћу кола твоја.',
        11: 'И затрћу градове у твојој земљи, и развалићу сва тврда мјеста твоја;',
        12: 'И истријебићу врачање из руку твојих, и нећеш имати гатара;',
        13: 'И истријебићу ликове твоје резане и ступове твоје исред тебе, и нећеш се више клањати дјелу руку својих;',
        14: 'И искоријенићу гајеве твоје исред тебе, и раскопаћу градове твоје,',
        15: 'И извршићу освету с гњевом и љутином на народима који не слушаше.',
    },
    6: {
        1: 'Слушајте шта говори Господ: устани, суди се с горама, и нека чују хумови глас твој.',
        2: 'Слушајте, горе и тврди темељи земаљски, парбу Господњу, јер Господ има парбу с народом својим, и с Израиљем се суди.',
        3: 'Народе мој, шта сам ти учинио? и чим сам ти досадио? Одговори ми.',
        4: 'Јер те изведох из земље Мисирске и искупих из куће ропске и послах пред тобом Мојсија, Арона и Марију.',
        5: 'Народе мој, опомени се што науми Валак цар Моавски и што му одговори Валам син Веоров, од Ситима до Галгала шта би, да познаш правду Господњу.',
        6: 'Су чим ћу доћи пред Господа да се поклоним Богу вишњему хоћу ли доћи преда њ са жртвама паљеницама? с теоцима од године?',
        7: 'Хоће ли Господу бити миле тисуће овнова? десетине тисућа потока уља? хоћу ли дати првенца својега за пријеступ свој? плод утробе своје за гријех душе своје?',
        8: 'Показао ти је, човјече, што је добро; и шта Господ иште од тебе осим да чиниш што је право и да љубиш милост и да ходиш смјерно с Богом својим?',
        9: 'Глас Господњи виче граду, и ко је мудар види име твоје; слушајте прут и онога који га је одредио.',
        10: 'Није ли јоште у кући безбожниковој благо неправо? и ефа крња, гадна?',
        11: 'Хоће ли ми бити чист у кога су мјерила лажна и у тобоцу пријеварно камење?',
        12: 'Јер су богатуни његови пуни неправде, и становници говоре лаж, и у устима им је језик пријеваран.',
        13: 'Зато ћу те и ја бити да оболиш, пустошићу те за гријехе твоје.',
        14: 'Ти ћеш јести, али се нећеш наситити, и падање твоје биће усред тебе; и склањаћеш, али нећеш избавити, и што избавиш предаћу мачу.',
        15: 'Ти ћеш сијати, али нећеш жети; ти ћеш циједити маслине, али се нећеш намазати уљем, и маст, али нећеш пити вина.',
        16: 'Јер се држе уредбе Амријеве и сва дјела дома Ахавова, и ходите по савјетима њиховијем, да те предам у погибао, и становнике његове у потсмијех, и носићете срамоту народа мојега.',
    },
    7: {
        1: 'Тешко мени! јер сам као кад се обере љетина, као кад се пабирчи послије брања виноградскога; нема грозда за јело, ранога воћа жели душа моја.',
        2: 'Неста побожнога са земље и нема правога међу људима, сви вребају крв, сваки лови брата својега мрежом.',
        3: 'Да чине зло објема рукама што више могу, иште кнез; и судија суди за плату, и ко је велик говори опачину душе своје, и сплећу је.',
        4: 'Најбољи је између њих као трн, најправији је гори од трњака; дан стражара твојих, похођење твоје, дође, сада ће се смести.',
        5: 'Не вјерујте пријатељу, не ослањајте се на вођа; од оне која ти на крилу лежи, чувај врата уста својих.',
        6: 'Јер син грди оца, кћи устаје на матер своју, снаха на свекрву своју, непријатељи су човјеку домашњи његови.',
        7: 'Али ја ћу Господа погледати, чекаћу Бога спасења својега; услишиће ме Бог мој.',
        8: 'Немој ми се радовати, непријатељице моја; ако падох, устаћу; ако сједим у мраку, Господ ће ми бити видјело.',
        9: 'Подносићу гњев Господњи, јер му згријеших, док не расправи парбу моју и да ми правицу; извешће ме на видјело, видјећу правду његову.',
        10: 'Непријатељица ће моја видјети, и срам ће је покрити, која ми говори: гдје је Господ Бог твој? очи ће је моје видјети; сада ће се она погазити као блато на улицама.',
        11: 'У које се вријеме сазидају зидови твоји, у то ће вријеме отићи заповијест надалеко;',
        12: 'У то ће вријеме долазити к теби од Асирске до тврдијех градова, и од тврдијех градова до ријеке, и од мора до мора, и од горе до горе.',
        13: 'А земља ће бити пуста са становника својих, за плод дјела њиховијех.',
        14: 'Паси народ свој с палицом својом, стадо нашљедства својега, које живи осамљено у шуми, усред Кармила; нека пасу по Васану и по Галаду, као у старо вријеме.',
        15: 'Као у вријеме кад си изашао из земље Мисирске показаћу му чудеса.',
        16: 'Народи ће видјети, и постидјеће се од све силе своје; метнуће руку на уста, уши ће им заглухнути.',
        17: 'Лизаће прах као змија; као бубине земаљске дркћући ижљешће из рупа својих; притрчаће уплашени ка Господу Богу нашему, и тебе ће се бојати.',
        18: 'Ко је Бог као ти? који прашта безакоње и пролази пријеступе остатку од нашљедства својега, не држи довијека гњева својега, јер му је мила милост.',
        19: 'Опет ће се смиловати на нас; погазиће наша безакоња; бацићеш у дубине морске све гријехе њихове.',
        20: 'Показаћеш истину Јакову, милост Авраму, како си се заклео оцима нашим у старо вријеме.',
    },
}
